UPDATE sa_document SET status = 'FAILED', error_message = #{errorMessage}
WHERE status IN ('UPLOADED','PARSING','CHUNKING','EMBEDDING')
  AND update_time < TIMESTAMPADD(SECOND, -#{timeoutSeconds}, CURRENT_TIMESTAMP)
ORDER BY update_time, id LIMIT #{batchSize}
